<?php
require_once '../../config/auth.php'; require_once '../../config/database.php'; requireRole('admin');
$id=(int)($_GET['id']??0); $stmt=$pdo->prepare("SELECT co.*,s.nama_lengkap,c.nama_kelas,ay.tahun_ajaran FROM class_officers co INNER JOIN students s ON s.id=co.student_id INNER JOIN classes c ON c.id=co.class_id INNER JOIN academic_years ay ON ay.id=co.academic_year_id WHERE co.id=?");$stmt->execute([$id]);$officer=$stmt->fetch(PDO::FETCH_ASSOC);if(!$officer){header('Location: index.php?error=Data pengurus tidak ditemukan');exit;}
$classes=$pdo->query('SELECT id,nama_kelas FROM classes ORDER BY nama_kelas')->fetchAll(PDO::FETCH_ASSOC);$years=$pdo->query('SELECT id,tahun_ajaran FROM academic_years ORDER BY tanggal_mulai DESC')->fetchAll(PDO::FETCH_ASSOC);$pageTitle='Edit Bendahara Kelas';require_once '../../includes/header.php';require_once '../../includes/sidebar.php'; ?>
<main class="main-content"><?php require_once '../../includes/navbar.php'; ?><section class="dashboard-container"><a href="index.php" class="btn btn-light mb-3"><i class="bi bi-arrow-left"></i> Kembali</a><div class="card border-0 shadow-sm"><div class="card-body"><h3>Edit Bendahara Kelas</h3><p class="text-muted"><?= htmlspecialchars($officer['nama_lengkap']) ?> — <?= htmlspecialchars($officer['nama_kelas']) ?></p><?php if(isset($_GET['error'])): ?><div class="alert alert-danger"><?= htmlspecialchars($_GET['error']) ?></div><?php endif ?><form method="post" action="proses_edit.php"><input type="hidden" name="id" value="<?= $id ?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Kelas</label><select name="class_id" class="form-select" required><?php foreach($classes as $class): ?><option value="<?= (int)$class['id'] ?>" <?= (int)$class['id']===(int)$officer['class_id']?'selected':'' ?>><?= htmlspecialchars($class['nama_kelas']) ?></option><?php endforeach ?></select></div><div class="col-md-6"><label class="form-label">Tahun ajaran</label><select name="academic_year_id" class="form-select" required><?php foreach($years as $year): ?><option value="<?= (int)$year['id'] ?>" <?= (int)$year['id']===(int)$officer['academic_year_id']?'selected':'' ?>><?= htmlspecialchars($year['tahun_ajaran']) ?></option><?php endforeach ?></select></div><div class="col-md-6"><label class="form-label">Tanggal mulai</label><input type="date" name="tanggal_mulai" class="form-control" required value="<?= htmlspecialchars($officer['tanggal_mulai']) ?>"></div><div class="col-md-6"><label class="form-label">Tanggal selesai</label><input type="date" name="tanggal_selesai" class="form-control" value="<?= htmlspecialchars($officer['tanggal_selesai']??'') ?>"></div><div class="col-md-6"><label class="form-label">Status</label><select name="status" class="form-select"><option value="aktif" <?= $officer['status']==='aktif'?'selected':'' ?>>Aktif</option><option value="nonaktif" <?= $officer['status']==='nonaktif'?'selected':'' ?>>Nonaktif</option><option value="menunggu" <?= $officer['status']==='menunggu'?'selected':'' ?>>Menunggu</option></select></div></div><button class="btn btn-primary mt-4"><i class="bi bi-save"></i> Simpan</button></form></div></div></section></main><?php require_once '../../includes/footer.php'; ?>
